INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 22, 'theory', 'Quiz: files, permissions, atomic writes');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 22, 0, 'Why is the temporary file for an atomic replace created in the same directory as the target?', '["So that fsync is not needed", "So that the file name is shorter", "So that rename does not cross a filesystem boundary and fail with EXDEV", "So that the umask is not applied"]', 2, 'A rename is atomic only inside one filesystem; between two it fails with EXDEV. The target''s directory is guaranteed to be on the same filesystem as the target itself.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 22, 1, 'What does Path(''/srv/app'') / ''/etc/passwd'' return?', '["PosixPath(''/etc/passwd'')", "PosixPath(''/srv/app/etc/passwd'')", "PosixPath(''/srv/app//etc/passwd'')", "A ValueError is raised"]', 0, 'An absolute right operand discards the left side. So ''base / user input'' cannot be trusted without checking the result.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 22, 2, 'The umask is 022. A file is created through os.open with mode 0o666. Which mode does it get?', '["0o666", "0o622", "0o755", "0o644"]', 3, 'The mode at creation is requested & ~umask: 0o666 & ~0o022 = 0o644. A later chmod does not obey the mask.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 22, 3, 'Why is flock more robust than an O_EXCL lock file with a PID when a process dies abnormally?', '["It works on any network filesystem without exceptions", "The kernel drops the lock when the process dies, so no stale lock remains", "It forbids other programs from opening the file", "It writes the owner''s PID by itself"]', 1, 'The lock belongs to an open file description and disappears when all its descriptors are closed, including when the process dies. It is advisory, though: other programs may still write into the file.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 22, 4, 'In a directory-escape check, why is resolve() called before is_relative_to()?', '["is_relative_to() works only with existing files", "resolve() checks the file''s permissions", "is_relative_to() compares only text and follows neither links nor ''..''", "resolve() makes the path shorter"]', 2, 'is_relative_to() is purely string-based. Only resolve() follows symbolic links and removes ''..'', after which comparing with the resolved base makes sense.');
